#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / "upstream"
client_probe = ROOT / "fabric/src/main/java/org/valkyrienskies/mod/fabric/client/GateEClientProbe.java"
source = client_probe.read_text(encoding="utf-8")

anchor = '''            var playerBox = player.getBoundingBox();\n            boolean collisionEligible = carriage.canCollideWith(player);'''
insert = '''            var playerBox = player.getBoundingBox();\n            String simplifiedColliderState = "unresolved";\n            try {\n                java.lang.reflect.Method getContraptionForCollider = carriage.getClass().getMethod("getContraption");\n                Object contraptionForCollider = getContraptionForCollider.invoke(carriage);\n                if (contraptionForCollider == null) {\n                    simplifiedColliderState = "contraption=null";\n                } else {\n                    java.lang.reflect.Method getSimplified = contraptionForCollider.getClass().getMethod("getSimplifiedEntityColliders");\n                    Object simplified = getSimplified.invoke(contraptionForCollider);\n                    if (simplified == null) {\n                        simplifiedColliderState = "null";\n                    } else {\n                        Class<?> collisionListClass = simplified.getClass();\n                        int size = collisionListClass.getField("size").getInt(simplified);\n                        double[] centerX = (double[]) collisionListClass.getField("centerX").get(simplified);\n                        double[] centerY = (double[]) collisionListClass.getField("centerY").get(simplified);\n                        double[] centerZ = (double[]) collisionListClass.getField("centerZ").get(simplified);\n                        double[] extentsX = (double[]) collisionListClass.getField("extentsX").get(simplified);\n                        double[] extentsY = (double[]) collisionListClass.getField("extentsY").get(simplified);\n                        double[] extentsZ = (double[]) collisionListClass.getField("extentsZ").get(simplified);\n                        java.lang.reflect.Method toLocalForCollider = carriage.getClass().getMethod("toLocalVector", Vec3.class, float.class);\n                        Vec3 localFeetForCollider = (Vec3) toLocalForCollider.invoke(carriage, player.position(), 0.0f);\n                        double nearestGapSq = Double.POSITIVE_INFINITY;\n                        int nearestIndex = -1;\n                        boolean xzInsideAny = false;\n                        double highestTopUnderFeet = -Double.MAX_VALUE;\n                        for (int i = 0; i < size; i++) {\n                            double minX = centerX[i] - extentsX[i];\n                            double maxX = centerX[i] + extentsX[i];\n                            double minY = centerY[i] - extentsY[i];\n                            double maxY = centerY[i] + extentsY[i];\n                            double minZ = centerZ[i] - extentsZ[i];\n                            double maxZ = centerZ[i] + extentsZ[i];\n                            double dx = localFeetForCollider.x < minX ? minX - localFeetForCollider.x : (localFeetForCollider.x > maxX ? localFeetForCollider.x - maxX : 0.0);\n                            double dy = localFeetForCollider.y < minY ? minY - localFeetForCollider.y : (localFeetForCollider.y > maxY ? localFeetForCollider.y - maxY : 0.0);\n                            double dz = localFeetForCollider.z < minZ ? minZ - localFeetForCollider.z : (localFeetForCollider.z > maxZ ? localFeetForCollider.z - maxZ : 0.0);\n                            double gapSq = dx * dx + dy * dy + dz * dz;\n                            if (gapSq < nearestGapSq) {\n                                nearestGapSq = gapSq;\n                                nearestIndex = i;\n                            }\n                            if (localFeetForCollider.x >= minX && localFeetForCollider.x <= maxX && localFeetForCollider.z >= minZ && localFeetForCollider.z <= maxZ) {\n                                xzInsideAny = true;\n                                if (maxY <= localFeetForCollider.y + 0.5 && maxY > highestTopUnderFeet) highestTopUnderFeet = maxY;\n                            }\n                        }\n                        String nearest = "none";\n                        if (nearestIndex >= 0) {\n                            nearest = "i=" + nearestIndex\n                                + ",center=" + centerX[nearestIndex] + "," + centerY[nearestIndex] + "," + centerZ[nearestIndex]\n                                + ",extents=" + extentsX[nearestIndex] + "," + extentsY[nearestIndex] + "," + extentsZ[nearestIndex]\n                                + ",top=" + (centerY[nearestIndex] + extentsY[nearestIndex]);\n                        }\n                        double verticalGap = highestTopUnderFeet == -Double.MAX_VALUE ? Double.NaN : localFeetForCollider.y - highestTopUnderFeet;\n                        simplifiedColliderState = "type=" + collisionListClass.getName()\n                            + ";size=" + size\n                            + ";local_feet=" + localFeetForCollider.x + "," + localFeetForCollider.y + "," + localFeetForCollider.z\n                            + ";nearest_gap_sq=" + nearestGapSq\n                            + ";nearest=" + nearest\n                            + ";xz_inside_any=" + xzInsideAny\n                            + ";highest_top_under_feet=" + highestTopUnderFeet\n                            + ";vertical_gap=" + verticalGap;\n                    }\n                }\n            } catch (ReflectiveOperationException | RuntimeException exception) {\n                simplifiedColliderState = "error=" + exception.getClass().getSimpleName();\n            }\n            boolean collisionEligible = carriage.canCollideWith(player);'''

if "simplifiedColliderState" not in source:
    if anchor not in source:
        raise SystemExit("Phase 66 could not find Gate E player-box anchor")
    source = source.replace(anchor, insert, 1)

old_log = '''                collisionEligible, broadphaseOverlap, player.isAlive(), createRegisteredContact, contactFieldState, localSupportState);'''
new_log = '''                collisionEligible, broadphaseOverlap, player.isAlive(), createRegisteredContact, contactFieldState,\n                localSupportState + ";simplified_colliders=" + simplifiedColliderState);'''
if old_log not in source:
    raise SystemExit("Phase 66 could not find Gate E state log arguments")
source = source.replace(old_log, new_log, 1)

client_probe.write_text(source, encoding="utf-8")
print("Phase 66: traced Create's prebuilt simplified collider geometry around the normalized LocalPlayer to distinguish missing collider data from OBB separation failure; read-only telemetry only")
